"""Report coverage of the certified source, unioned across build configurations.

gcovr's --add-tracefile merge keys every branch by the basic-block pair gcov
assigned it. Those block numbers are not a property of the source: a file that
compiles to a different amount of code in two configurations gets its blocks
renumbered, so the same source branch arrives under two identities and the merge
counts it twice. GUIX has eighteen build configurations, and the feature macros
they select -- bidi text, mouse support, partial canvas, error checking -- change
how much code a file compiles to.

That inflation is symmetric for a branch covered everywhere, so the percentage
stays plausible and the fault is easy to miss. It is not harmless: the figure a
certification report quotes as "branches in the certified source" has to be
branches in the certified source, and the number grows or shrinks when a build
configuration is added for reasons that have nothing to do with the code.

This script reports the union instead. A line is covered if any configuration
executed it. A branch is keyed by its file and line, the number of branches the
line compiles to, and its position among them -- "the Nth of the N branches this
line carries" -- and is covered if any configuration that compiles that form of
the line took it.

The branch count is in the key because position alone does not identify a
branch on this tree. Position is stable only while every configuration that
compiles a line agrees on how many branches it carries, and three lines do not:
each is a switch with a case under #if, two for dynamic bidi text and one for
mouse support, so the macro set decides how many branches the switch has and the
Nth branch is a different branch in different configurations. Keyed by position,
those three report every outcome covered; keyed by form, four outcomes in the
bidi and mouse forms are never taken. A key that overstates coverage is the one
error this report must not make.

The cost is that a line with two forms has its branches counted once per form,
so the denominator is conservative rather than exact. The lines that carry more
than one form are printed with the figure, with how many configurations compile
each, so a denominator that counts a line twice says so on its face.

Both figures are kept. gcovr's merged report is still produced and published
unchanged -- it is the tool's own output and nothing here rewrites it.
"""

import glob
import json
import math
import os
import sys


# The regression-test hook code a test build injects into the certified
# source, which would not be part of the certified denominator.
#
# This list is empty, and that is a measurement rather than an omission. Every
# -D on the compile line of a common/src object was enumerated and classified:
# GUIX has no GX_REGRESSION_TEST -- the string appears nowhere in the
# repository -- and the Linux port header carries no test-gated block and no
# *_EXTENSION family. No macro the test build defines adds code to certified
# source, so there is no site to exclude. A test build macro that later adds
# such a block would put its sites here, and every entry must then match a line
# the report carries or this fails.
#
# What the test build does override is disclosed rather than excluded, because
# a constant has no lines to remove: GX_CURSOR_BLINK_INTERVAL, shipped at 20 and
# set to 1 here.
HOOK_SITES = []

# Sites where a hook displaces shipped code rather than occupying an empty line,
# so that only its branches may come out. Empty for the reason above.
HOOK_BRANCH_SITES = []


def exclude_hook_sites(lines, branches):
    """Drop the hook expansions from the union, and report what was dropped.

    Returns one row per site: the macro, and the covered/total it took out of
    each axis, so the output shows on its face that the exclusion removed
    nothing that was uncovered.
    """

    report = []
    missing = []

    for path, number, macro, drop_line in (
            [(p, n, m, True) for p, n, m in HOOK_SITES] +
            [(p, n, m, False) for p, n, m in HOOK_BRANCH_SITES]):

        outcomes = sorted(k for k in branches if k[0] == path and k[1] == number)
        if (path, number) not in lines:
            missing.append((path, number, macro))
            continue

        line_covered = line_total = 0
        if drop_line:
            line_covered, line_total = lines.pop((path, number)), 1

        outcome_covered = sum(branches.pop(k) for k in outcomes)
        report.append((path, number, macro, drop_line,
                       line_covered, line_total, outcome_covered, len(outcomes)))

    return report, missing


def union(tracefiles):
    """Union line and branch coverage across per-configuration tracefiles.

    Also returns, per (file, line), the branch count each configuration
    compiled it with, which is what the keying-soundness check reads, and the
    configurations that covered no line at all.
    """

    lines = {}
    branches = {}
    shapes = {}
    silent = []

    for path in tracefiles:
        configuration = os.path.basename(path)[:-len(".json")]
        with open(path, encoding="utf-8") as handle:
            data = json.load(handle)

        covered_here = 0
        for entry in data.get("files", []):
            name = entry["file"]
            for line in entry.get("lines", []):
                number = line["line_number"]
                key = (name, number)
                hit = 1 if line["count"] > 0 else 0
                covered_here += hit
                lines[key] = lines.get(key, 0) or hit

                outcomes = line.get("branches", [])
                if outcomes:
                    shapes.setdefault(key, {})[configuration] = len(outcomes)

                for index, branch in enumerate(outcomes):
                    key = (name, number, len(outcomes), index)
                    branches[key] = branches.get(key, 0) or (1 if branch["count"] > 0 else 0)

        if covered_here == 0:
            silent.append(configuration)

    return lines, branches, shapes, silent


def multiform_lines(shapes):
    """Lines whose branch count differs between configurations that compile them.

    These are the lines the branch count in the key exists for, and each
    contributes its branches once per form. A configuration that does not
    compile a line contributes no entry, so absence is not a second form; nor
    does one that compiles the line with no branches at all, since every branch
    the line has elsewhere still has a single identity.
    """

    return sorted(
        (path, number, counts)
        for (path, number), counts in shapes.items()
        if len(set(counts.values())) > 1)


def truncate(rate):
    """Round a percentage down to the two decimal places the report prints.

    Rounding to nearest would print a figure above the ratio it stands for, and
    a coverage report that overstates coverage, even by a hundredth, is the
    wrong error for certification evidence to make. It also keeps the report
    and a gate in step: the threshold is compared against the full-precision
    ratio, so a gate set to a rounded-up figure fails a tree in which nothing
    has regressed. Truncating here makes the printed figure the one a threshold
    can safely be set to.
    """

    return math.floor(rate * 100) / 100


def main():
    if len(sys.argv) < 4:
        print("usage: coverage_union.py <tracefile-dir> <min-line> <min-branch>", file=sys.stderr)
        return 2

    directory, min_line, min_branch = sys.argv[1], float(sys.argv[2]), float(sys.argv[3])

    tracefiles = sorted(glob.glob(os.path.join(directory, "*.json")))
    if not tracefiles:
        print("coverage_union.py: no JSON in %s." % directory, file=sys.stderr)
        print("Run the suites with TX_COVERAGE=ON first.", file=sys.stderr)
        return 1

    lines, branches, shapes, silent = union(tracefiles)
    if not lines:
        print("coverage_union.py: the tracefiles contain no files.", file=sys.stderr)
        return 1

    # A configuration in the merge set that covered nothing adds nothing to a
    # union, so its collapse is invisible in the figure. Either its tests did
    # not run -- a configuration that builds and then fails every test still
    # writes a full-shaped report of zeros -- or every test it ran asserts on a
    # feature it compiles out. Either way the remedy is a decision rather than a
    # retry, so it stops here.
    if silent:
        print("coverage_union.py: %d configuration(s) covered no certified line:"
              % len(silent), file=sys.stderr)
        for name in silent:
            print("    %s" % name, file=sys.stderr)
        print("Each is in the merge set and adds nothing to the union. Make its", file=sys.stderr)
        print("tests run, or take it out of the merge set by a recorded decision.", file=sys.stderr)
        return 1

    multiform = multiform_lines(shapes)

    excluded, missing = exclude_hook_sites(lines, branches)
    if missing:
        for path, number, macro in missing:
            print("coverage_union.py: %s:%d is not in the report -- %s has moved."
                  % (path, number, macro), file=sys.stderr)
        print("coverage_union.py: re-derive HOOK_SITES from the port header.", file=sys.stderr)
        return 1

    line_covered, line_total = sum(lines.values()), len(lines)
    branch_covered, branch_total = sum(branches.values()), len(branches)
    files = len({path for path, _ in lines})

    line_rate = (100.0 * line_covered) / line_total
    branch_rate = (100.0 * branch_covered) / branch_total if branch_total else 100.0

    print("coverage_union.py: unioned over %d configuration(s):" % len(tracefiles))
    for path in tracefiles:
        print("    %s" % os.path.basename(path)[:-len(".json")])

    # What the branch count in the key costs, on the face of the output.
    print("    %d line(s) carry branches; %d compile to more than one form"
          % (len(shapes), len(multiform)))
    for path, number, counts in multiform:
        forms = {}
        for count in counts.values():
            forms[count] = forms.get(count, 0) + 1
        spread = ", ".join("%d branches in %d configuration(s)" % (n, c)
                           for n, c in sorted(forms.items()))
        print("        %-60s %s" % ("%s:%d" % (path, number), spread))
    print("    excluded, regression-test hook expansions: %s"
          % ("none" if not excluded else ""))
    for path, number, macro, drop_line, lc, lt, oc, ot in excluded:
        print("        %-44s lines %d/%d, outcomes %2d/%-2d  %s%s"
              % ("%s:%d" % (path, number), lc, lt, oc, ot, macro,
                 "" if drop_line else ", branches only"))

    print("    files    %d" % files)
    print("    lines    %d/%d - %.2f%%" % (line_covered, line_total, truncate(line_rate)))
    print("    branches %d/%d - %.2f%%" % (branch_covered, branch_total, truncate(branch_rate)))

    status = 0
    if line_rate < min_line:
        print("coverage_union.py: failed minimum line coverage (got %.2f%%, minimum %.2f%%)"
              % (truncate(line_rate), min_line), file=sys.stderr)
        status = 1
    if branch_rate < min_branch:
        print("coverage_union.py: failed minimum branch coverage (got %.2f%%, minimum %.2f%%)"
              % (truncate(branch_rate), min_branch), file=sys.stderr)
        status = 1

    return status


if __name__ == "__main__":
    sys.exit(main())
